-- Immutable physical branch IDs extend the existing places table.
ALTER TABLE places ADD COLUMN business_type text;
ALTER TABLE places ADD COLUMN consumer_eligible boolean NOT NULL DEFAULT true;
ALTER TABLE places ADD COLUMN locality jsonb;
ALTER TABLE places ADD COLUMN submitted_by text;
ALTER TABLE places ADD COLUMN submitting_tenant_id uuid REFERENCES tenants(id);
CREATE POLICY place_submission_create ON places FOR INSERT WITH CHECK(state='pending' AND submitted_by=current_setting('app.actor_id',true) AND is_tenant_owner(submitting_tenant_id));
CREATE POLICY place_submission_read ON places FOR SELECT USING(submitted_by=current_setting('app.actor_id',true) OR can_access_tenant(submitting_tenant_id));
ALTER TABLE memberships DROP CONSTRAINT memberships_role_check;
ALTER TABLE memberships ADD CONSTRAINT memberships_role_check CHECK(role IN('owner','manager','editor','viewer'));
ALTER TABLE memberships ADD COLUMN scope_mode text NOT NULL DEFAULT 'all' CHECK(scope_mode IN('all','selected'));
ALTER TABLE memberships ADD COLUMN can_publish boolean NOT NULL DEFAULT false;
ALTER TABLE memberships ADD COLUMN can_manage_destinations boolean NOT NULL DEFAULT false;
CREATE TABLE membership_places(tenant_id uuid NOT NULL,user_id text NOT NULL,place_id text NOT NULL REFERENCES places,PRIMARY KEY(tenant_id,user_id,place_id),FOREIGN KEY(tenant_id,user_id) REFERENCES memberships ON DELETE CASCADE);
ALTER TABLE membership_places ENABLE ROW LEVEL SECURITY; ALTER TABLE membership_places FORCE ROW LEVEL SECURITY;
CREATE POLICY member_scope_read ON membership_places FOR SELECT USING(user_id=current_setting('app.actor_id',true) OR is_tenant_owner(tenant_id));
CREATE POLICY member_scope_write ON membership_places FOR ALL USING(is_tenant_owner(tenant_id)) WITH CHECK(is_tenant_owner(tenant_id));
CREATE OR REPLACE FUNCTION can_access_tenant(tid uuid,write boolean DEFAULT false) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT EXISTS(SELECT 1 FROM memberships WHERE tenant_id=tid AND user_id=current_setting('app.actor_id',true) AND state='active' AND (NOT write OR role IN('owner','manager','editor'))) $$;
CREATE FUNCTION can_access_place(tid uuid,pid text,write boolean DEFAULT false) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT EXISTS(SELECT 1 FROM memberships m WHERE m.tenant_id=tid AND m.user_id=current_setting('app.actor_id',true) AND m.state='active' AND (NOT write OR m.role IN('owner','manager','editor')) AND (m.role='owner' OR m.scope_mode='all' OR EXISTS(SELECT 1 FROM membership_places s WHERE s.tenant_id=tid AND s.user_id=m.user_id AND s.place_id=pid))) $$;
-- Scope private business rows at the database boundary too.
DROP POLICY merchant_claim_read ON merchant_claims;
CREATE POLICY merchant_claim_read ON merchant_claims FOR SELECT USING(can_access_place(tenant_id,place_id));
DROP POLICY merchant_claim_create ON merchant_claims;
CREATE POLICY merchant_claim_create ON merchant_claims FOR INSERT WITH CHECK(can_access_place(tenant_id,place_id,true) AND submitted_by=current_setting('app.actor_id',true) AND state='submitted');
DROP POLICY merchant_draft_read ON merchant_drafts;
CREATE POLICY merchant_draft_read ON merchant_drafts FOR SELECT USING(can_access_place(tenant_id,place_id));
DROP POLICY merchant_draft_create ON merchant_drafts;
CREATE POLICY merchant_draft_create ON merchant_drafts FOR INSERT WITH CHECK(can_access_place(tenant_id,place_id,true) AND created_by=current_setting('app.actor_id',true));
DROP POLICY merchant_draft_update ON merchant_drafts;
CREATE POLICY merchant_draft_update ON merchant_drafts FOR UPDATE USING(can_access_place(tenant_id,place_id,true)) WITH CHECK(can_access_place(tenant_id,place_id,true));
DROP POLICY publication_read ON publications;
CREATE POLICY publication_read ON publications FOR SELECT USING(can_access_place(tenant_id,place_id));
DROP POLICY publication_create ON publications;
CREATE POLICY publication_create ON publications FOR INSERT WITH CHECK(can_access_place(tenant_id,place_id,true));
CREATE TABLE service_grants(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants,place_id text NOT NULL REFERENCES places,kind text NOT NULL DEFAULT 'pilot' CHECK(kind='pilot'),starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,revoked_at timestamptz,reason text NOT NULL,issued_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),CHECK(ends_at>starts_at AND ends_at<=starts_at+interval '90 days'));
ALTER TABLE service_grants ENABLE ROW LEVEL SECURITY;ALTER TABLE service_grants FORCE ROW LEVEL SECURITY;
CREATE POLICY grant_read ON service_grants FOR SELECT USING(can_access_place(tenant_id,place_id));
ALTER TABLE payment_ledger ADD COLUMN disputed_at timestamptz;
ALTER TABLE subscriptions ADD COLUMN renewal_failed_at timestamptz;
ALTER TABLE subscriptions ADD COLUMN renewals_paused_at timestamptz;
ALTER TABLE subscriptions ADD COLUMN first_delivery_due_at timestamptz;
ALTER TABLE subscriptions ADD COLUMN first_delivery_verified_at timestamptz;
ALTER TABLE subscriptions ADD COLUMN plan_terms_version text;
ALTER TABLE subscriptions ADD COLUMN plan_terms_accepted_at timestamptz;
-- Preserve each provider attempt; a terminal attempt never prevents a later restart.
ALTER TABLE subscriptions DROP CONSTRAINT subscriptions_tenant_id_place_id_key;
CREATE UNIQUE INDEX subscription_one_open ON subscriptions(tenant_id,place_id) WHERE status NOT IN('cancelled','completed','expired','abandoned');
CREATE TABLE team_invitations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants,email text NOT NULL,token_hash text UNIQUE NOT NULL,role text NOT NULL CHECK(role IN('manager','editor','viewer')),scope_mode text NOT NULL CHECK(scope_mode IN('all','selected')),place_ids text[] NOT NULL DEFAULT '{}',can_publish boolean NOT NULL DEFAULT false,can_manage_destinations boolean NOT NULL DEFAULT false,created_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL,accepted_at timestamptz,accepted_by text,revoked_at timestamptz,CHECK(expires_at>created_at));
ALTER TABLE team_invitations ENABLE ROW LEVEL SECURITY;ALTER TABLE team_invitations FORCE ROW LEVEL SECURITY;
CREATE POLICY invitation_owner ON team_invitations FOR ALL USING(is_tenant_owner(tenant_id)) WITH CHECK(is_tenant_owner(tenant_id));
CREATE FUNCTION accept_team_invitation(digest text,recipient text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE i team_invitations; actor text:=current_setting('app.actor_id',true); n integer; BEGIN IF length(actor)=0 OR actor IS NULL THEN RAISE EXCEPTION 'sign_in_required';END IF; SELECT * INTO i FROM team_invitations WHERE token_hash=digest FOR UPDATE; IF i.id IS NULL OR i.email<>lower(recipient) OR i.expires_at<=now() OR i.accepted_at IS NOT NULL OR i.revoked_at IS NOT NULL THEN RETURN NULL;END IF;PERFORM pg_advisory_xact_lock(hashtextextended('team:'||i.tenant_id,0)); SELECT count(*) INTO n FROM memberships WHERE tenant_id=i.tenant_id AND state='active' AND role<>'owner'; IF n>=2 AND NOT EXISTS(SELECT 1 FROM memberships WHERE tenant_id=i.tenant_id AND user_id=actor AND state='active') THEN RAISE EXCEPTION 'team_limit';END IF; IF EXISTS(SELECT 1 FROM memberships WHERE tenant_id=i.tenant_id AND user_id=actor AND role='owner') THEN RETURN NULL;END IF; INSERT INTO memberships(tenant_id,user_id,role,state,scope_mode,can_publish,can_manage_destinations) VALUES(i.tenant_id,actor,i.role,'active',i.scope_mode,i.can_publish,i.can_manage_destinations) ON CONFLICT(tenant_id,user_id) DO UPDATE SET role=EXCLUDED.role,state='active',scope_mode=EXCLUDED.scope_mode,can_publish=EXCLUDED.can_publish,can_manage_destinations=EXCLUDED.can_manage_destinations;DELETE FROM membership_places WHERE tenant_id=i.tenant_id AND user_id=actor;INSERT INTO membership_places SELECT i.tenant_id,actor,unnest(i.place_ids);UPDATE team_invitations SET accepted_at=now(),accepted_by=actor WHERE id=i.id; RETURN i.tenant_id; END $$;
CREATE TABLE service_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid REFERENCES tenants,actor_id text NOT NULL,place_id text REFERENCES places,kind text NOT NULL CHECK(kind IN('support','correction','deletion','ownership_transfer','refund','delivery_incident','export')),body jsonb NOT NULL,state text NOT NULL DEFAULT 'open' CHECK(state IN('open','in_review','resolved','declined')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),resolution text);
ALTER TABLE service_requests ENABLE ROW LEVEL SECURITY;ALTER TABLE service_requests FORCE ROW LEVEL SECURITY;
CREATE POLICY service_request_read ON service_requests FOR SELECT USING(actor_id=current_setting('app.actor_id',true) OR (tenant_id IS NOT NULL AND is_tenant_owner(tenant_id)));
CREATE POLICY service_request_create ON service_requests FOR INSERT WITH CHECK(actor_id=current_setting('app.actor_id',true) AND (tenant_id IS NULL OR can_access_tenant(tenant_id)) AND state='open');
CREATE TABLE account_preferences(user_id text PRIMARY KEY,body jsonb NOT NULL DEFAULT '{}',revision int NOT NULL DEFAULT 1,updated_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE account_preferences ENABLE ROW LEVEL SECURITY;ALTER TABLE account_preferences FORCE ROW LEVEL SECURITY;
CREATE POLICY preference_own ON account_preferences FOR ALL USING(user_id=current_setting('app.actor_id',true)) WITH CHECK(user_id=current_setting('app.actor_id',true));
ALTER TABLE subscriptions ADD COLUMN next_reconcile_at timestamptz NOT NULL DEFAULT now();
ALTER TABLE subscriptions ADD COLUMN reconcile_error text;
CREATE TABLE billing_commands(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),subscription_id uuid NOT NULL REFERENCES subscriptions,kind text NOT NULL CHECK(kind IN('cancel','pause','resume','refund')),payload jsonb NOT NULL DEFAULT '{}',state text NOT NULL DEFAULT 'queued' CHECK(state IN('queued','running','succeeded','reconciliation_required','failed')),attempts integer NOT NULL DEFAULT 0,lease_until timestamptz,error_code text,provider_reference text,created_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz);
CREATE UNIQUE INDEX billing_one_command ON billing_commands(subscription_id,kind) WHERE state IN('queued','running','reconciliation_required');
ALTER TABLE billing_commands ENABLE ROW LEVEL SECURITY;ALTER TABLE billing_commands FORCE ROW LEVEL SECURITY;
CREATE POLICY billing_command_read ON billing_commands FOR SELECT USING(EXISTS(SELECT 1 FROM subscriptions s WHERE s.id=subscription_id AND is_tenant_owner(s.tenant_id)));
CREATE POLICY billing_command_create ON billing_commands FOR INSERT WITH CHECK(EXISTS(SELECT 1 FROM subscriptions s WHERE s.id=subscription_id AND is_tenant_owner(s.tenant_id)) AND kind IN('cancel','resume'));
CREATE TABLE business_notifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants,place_id text REFERENCES places,event_key text UNIQUE NOT NULL,kind text NOT NULL,title text NOT NULL,body text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),acknowledged_at timestamptz,email_state text NOT NULL DEFAULT 'pending' CHECK(email_state IN('pending','sent','unconfigured','failed')),email_attempts integer NOT NULL DEFAULT 0,next_attempt_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE business_notifications ENABLE ROW LEVEL SECURITY;ALTER TABLE business_notifications FORCE ROW LEVEL SECURITY;
CREATE POLICY business_notification_read ON business_notifications FOR SELECT USING(can_access_tenant(tenant_id) AND (place_id IS NULL OR can_access_place(tenant_id,place_id)));
CREATE POLICY business_notification_ack ON business_notifications FOR UPDATE USING(is_tenant_owner(tenant_id)) WITH CHECK(is_tenant_owner(tenant_id));
CREATE TABLE billing_disputes(provider_id text PRIMARY KEY,payment_id text NOT NULL REFERENCES payment_ledger(payment_id),status text NOT NULL,evidence jsonb NOT NULL,updated_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE billing_disputes ENABLE ROW LEVEL SECURITY;ALTER TABLE billing_disputes FORCE ROW LEVEL SECURITY;
CREATE POLICY billing_dispute_read ON billing_disputes FOR SELECT USING(EXISTS(SELECT 1 FROM payment_ledger l JOIN subscriptions s ON s.id=l.subscription_id WHERE l.payment_id=billing_disputes.payment_id AND is_tenant_owner(s.tenant_id)));
